package cl.acis.ordenes.controller;
import cl.acis.ordenes.config.ActorHeaders; import cl.acis.ordenes.dto.*; import cl.acis.ordenes.service.OrdenService; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest; import org.springframework.boot.test.mock.mockito.MockBean; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(OrdenController.class) class OrdenControllerTest { @Autowired MockMvc mvc; @MockBean OrdenService service; @MockBean ActorHeaders headers;
 @Test void crearValidoResponde200() throws Exception {when(headers.leer(any())).thenReturn(new ActorHeaders.Actor(1L,"JEFATURA"));when(service.crear(any(),eq(1L))).thenReturn(null);mvc.perform(post("/api/ordenes").header("X-Usuario-Id","1").header("X-Usuario-Rol","JEFATURA").contentType(MediaType.APPLICATION_JSON).content("{\"clienteId\":5,\"tipoServicio\":\"Mantención\",\"prioridad\":\"ALTA\",\"fechaProgramada\":\"2026-12-01T10:00:00\",\"descripcion\":\"Revisar\"}")).andExpect(status().isOk());}
 @Test void accionSinHeaderResponde401() throws Exception {when(headers.leer(any())).thenThrow(new cl.acis.ordenes.exception.NoAutorizadoException("Faltan headers"));mvc.perform(post("/api/ordenes/1/acciones").contentType(MediaType.APPLICATION_JSON).content("{\"accion\":\"ACEPTAR\"}")).andExpect(status().isUnauthorized());}
 @Test void accionCheckoutSinFotoResponde400() throws Exception {when(headers.leer(any())).thenReturn(new ActorHeaders.Actor(3L,"TECNICO"));when(service.accion(anyLong(),any(),eq("TECNICO"),eq(3L))).thenThrow(new cl.acis.ordenes.exception.ReglaNegocioException("foto"));mvc.perform(post("/api/ordenes/1/acciones").header("X-Usuario-Id","3").header("X-Usuario-Rol","TECNICO").contentType(MediaType.APPLICATION_JSON).content("{\"accion\":\"CHECK_OUT\",\"diagnostico\":\"d\",\"actividades\":\"a\",\"cantidadFotosEvidencia\":0}")).andExpect(status().isBadRequest());}
}
